def install(rules):
    """Apply translations without changing the established economy or ending IDs."""
    for e in list(rules.DISCOVERIES.values()) + [e for pool in rules.POOLS.values() for e in pool]:
        e['text'] = TEXT[e['title']][1]
        for c, pair in zip(e['choices'], RESULTS[e['title']]):
            c['narrative'] = pair[1]
    rules.TALKS = [(title, pair[1]) for title, pair in TALKS.items()]
    rules.achievements.TALK_TITLES.update(TALKS)
    rules.ENDINGS = {key: (row[0], row[1], ENDINGS[key][1]) for key, row in rules.ENDINGS.items()}
    import journey_feedback
    journey_feedback.RESPONSES.update({k: [p[1] for p in v] for k, v in RESULTS.items()})
    journey_feedback.RESPONSES.update({k: [v[1]] for k, v in TALK_RESULTS.items()})


def next_thread(s, rules):
    for row in THREADS:
        if (s['loc'] != row['loc'] or row['id'] in s.setdefault('story_seen', [])
                or s['day'] < row.get('day', 1)
                or s['visits'].get(s['loc'], 0) < row.get('visit', 1)
                or row.get('flag') and row['flag'] not in s['flags']):
            continue
        s['story_seen'].append(row['id'])
        options = []
        for label, effect, cost, english, chinese in row['options']:
            c = rules.choice(label, effect, cost, result='经过与变化已记入手记。')
            c['narrative'] = chinese
            options.append(c)
        return rules.event(row['title'], row['zh'], options, '支线 / ' + rules.PLACES[s['loc']][0])
    return None


def night_text(s, day):
    key = 'storm' if day in (12, 13) else 'cold' if day in (6, 7) else s['loc']
    return NIGHTS[key][1]
